CREATE TABLE IF NOT EXISTS ledger_entries(id TEXT PRIMARY KEY,payment_transaction_id TEXT, payment_period TEXT,author_id TEXT,book_id TEXT,show_id TEXT,content_type TEXT,reward_type TEXT,source_earning_id TEXT,allocated_gross NUMERIC,allocated_net NUMERIC,finance_amount NUMERIC,finance_status TEXT,utr TEXT,ledger_state TEXT,allocation_method TEXT,created_at TEXT);